```ts
// profileCache.ts
import type { Redis } from "ioredis";

export interface Profile {
  id: string;
  [field: string]: unknown;
}

const TTL_SECONDS = 300;
const key = (userId: string) => `profile:v1:${userId}`;

export class ProfileCache {
  private inflight = new Map<string, Promise<Profile | null>>();

  constructor(
    private redis: Redis,
    private fetchProfile: (userId: string) => Promise<Profile | null>,
  ) {}

  async get(userId: string): Promise<Profile | null> {
    // Redis errors fall through to the source.
    const cached = await this.redis.get(key(userId)).catch(() => null);
    if (cached !== null) return JSON.parse(cached);

    // Concurrent misses for one user share a single fetch.
    let pending = this.inflight.get(userId);
    if (!pending) {
      pending = this.load(userId).finally(() => this.inflight.delete(userId));
      this.inflight.set(userId, pending);
    }
    return pending;
  }

  async invalidate(userId: string): Promise<void> {
    await this.redis.del(key(userId));
  }

  private async load(userId: string): Promise<Profile | null> {
    const profile = await this.fetchProfile(userId);
    if (profile) {
      await this.redis
        .set(key(userId), JSON.stringify(profile), "EX", TTL_SECONDS)
        .catch(() => {});
    }
    return profile;
  }
}
```

